// ── Validate payload ─────────────────────────────────────────────
// Mode: Run Once for All Items. Input: the Webhook item.
// Output: one item { valid, errors[], claim (normalised), received_at }
const body = $input.first().json.body;
const errors = [];

const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const str = (v) => (typeof v === 'string' ? v.trim() : '');

if (!isObj(body)) {
  return [{ json: { valid: false, errors: ['Body must be a JSON object'], claim: null } }];
}

const claimant = isObj(body.claimant) ? body.claimant : {};
if (!isObj(body.claimant)) errors.push('claimant is required and must be an object');

const claim = {
  idempotency_key: str(body.idempotency_key),
  policy_number:   str(body.policy_number).toUpperCase(),
  channel:         str(body.channel).toLowerCase() || 'api',
  claimant_name:   str(claimant.name),
  claimant_email:  str(claimant.email).toLowerCase(),
  claimant_phone:  str(claimant.phone) || null,
  incident_date:   str(body.incident_date),
  claimed_amount:  body.claimed_amount,
  currency:        (str(body.currency) || 'ZAR').toUpperCase(),
  description:     str(body.description),
};

// idempotency_key
if (!claim.idempotency_key) errors.push('idempotency_key is required');
else if (claim.idempotency_key.length < 8 || claim.idempotency_key.length > 100)
  errors.push('idempotency_key must be 8-100 characters');

// policy_number
if (!claim.policy_number) errors.push('policy_number is required');
else if (!/^POL-[A-Z]{3}-\d{6}$/.test(claim.policy_number))
  errors.push('policy_number must look like POL-XXX-123456');

// claimant
if (!claim.claimant_name) errors.push('claimant.name is required');
if (!claim.claimant_email) errors.push('claimant.email is required');
else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(claim.claimant_email))
  errors.push('claimant.email is not a valid email address');

// channel
const CHANNELS = ['web', 'whatsapp', 'email', 'call_centre', 'api'];
if (!CHANNELS.includes(claim.channel))
  errors.push(`channel must be one of: ${CHANNELS.join(', ')}`);

// incident_date: real calendar date, not in the future (SAST)
const today = $now.setZone('Africa/Johannesburg').toISODate();
if (!claim.incident_date) errors.push('incident_date is required');
else if (!/^\d{4}-\d{2}-\d{2}$/.test(claim.incident_date) || !DateTime.fromISO(claim.incident_date).isValid)
  errors.push('incident_date must be a real date in YYYY-MM-DD format');
else if (claim.incident_date > today)
  errors.push(`incident_date ${claim.incident_date} is in the future`);

// claimed_amount
if (claim.claimed_amount === undefined || claim.claimed_amount === null || claim.claimed_amount === '')
  errors.push('claimed_amount is required');
else if (typeof claim.claimed_amount !== 'number' || !Number.isFinite(claim.claimed_amount))
  errors.push('claimed_amount must be a number');
else if (claim.claimed_amount <= 0)
  errors.push('claimed_amount must be greater than 0');
else if (Number(claim.claimed_amount.toFixed(2)) !== claim.claimed_amount) // float-safe
  errors.push('claimed_amount can have at most 2 decimal places');

// currency
if (claim.currency !== 'ZAR') errors.push('currency must be ZAR');

// description
if (!claim.description) errors.push('description is required');
else if (claim.description.length < 10 || claim.description.length > 5000)
  errors.push('description must be 10-5000 characters');

return [{
  json: {
    valid: errors.length === 0,
    errors,
    claim,
    raw_payload: body,
    received_at: $now.toISO(),
  },
}];

// ── Check eligibility ────────────────────────────────────────────
// Mode: Run Once for All Items.
// Input: one row from Load_Policy_PG (policy columns are null if not found).
// Output: one item carrying everything later nodes need.
const v = $('Validate_Payload_Func').first().json;  // validated claim from earlier
const p = $input.first().json;                      // policy row from Postgres
const c = v.claim;
const reasons = [];

if (!p.policy_number) {
  reasons.push('policy_not_found');
} else {
  if (p.status !== 'active') reasons.push('policy_not_active');
  // Dates are 'YYYY-MM-DD' strings, so plain string comparison is safe
  if (c.incident_date < p.start_date || c.incident_date > p.end_date)
    reasons.push('incident_outside_cover');
  if (c.claimed_amount > p.sum_insured) reasons.push('amount_exceeds_sum_insured');
}

return [{
  json: {
    eligible: reasons.length === 0,
    reasons,
    claim: c,
    policy: p.policy_number ? p : null,
    prior_claims_12m: p.prior_claims_12m ?? 0,
    raw_payload: v.raw_payload,
    received_at: v.received_at,
  },
}];

// ── Build AI prompt ──────────────────────────────────────────────
// Builds the user message every LLM branch (and the mock) receives.
// Data minimisation: no name, email, phone or policy number goes to the LLM.
const e = $input.first().json;          // item from Check_Eligibility_Func
const c = e.claim;
const p = e.policy;

// Untrusted text: stop the claimant closing our tag, and drop curly braces
// (LangChain prompt templates treat {braces} as variables).
const description = c.description
  .replace(/<\s*\/?\s*claim_description\s*>/gi, '[tag removed]')
  .replace(/[{}]/g, (m) => (m === '{' ? '(' : ')'));

const user_prompt = [
  'Analyse this insurance claim.',
  '',
  `Product: ${p.product}`,
  `Sum insured: R ${p.sum_insured}`,
  `Policy start date: ${p.start_date}`,
  `Incident date: ${c.incident_date}`,
  `Reported date: ${$now.setZone('Africa/Johannesburg').toISODate()}`,
  `Claimed amount: R ${c.claimed_amount}`,
  `Channel: ${c.channel}`,
  '',
  '<claim_description>',
  description,
  '</claim_description>',
].join('\n');

return [{ json: { ...e, ai_input: { user_prompt, description } } }];

// ── Mock AI analysis (LLM_MODE=mock) ─────────────────────────────
// Deterministic, keyword-based stand-in for the LLM so the pipeline and the
// test suite run without an API key. Returns the same shape as the real
// chains: { output: { ...analysis } }.
const e = $input.first().json;
const text = e.ai_input.description.toLowerCase();
const has = (...words) => words.some((w) => text.includes(w));

// Lets the tests prove the failure path: this node's error output goes to
// Normalise_AI_Func exactly like a real LLM failure would.
// Deterministic stand-in for the injection detector (real modes use *_Detector chains).
// [[simulate_detector_failure]] lets the tests prove "detector unavailable" handling.
const injection_check = text.includes('[[simulate_detector_failure]]')
  ? { flagged: false, confidence: null, failed: true }
  : has('ignore previous', 'ignore all previous', 'system prompt', 'you are now', 'automated reviewer', 'pre-approved')
    ? { flagged: true, confidence: 0.9, failed: false }
    : { flagged: false, confidence: 0.05, failed: false };

if (text.includes('[[simulate_llm_failure]]')) {
  throw new Error('Simulated LLM failure (mock mode)');
}

let a;
if (has('windscreen', 'windshield', 'glass')) {
  a = { claim_type: 'windscreen', severity: 'low', ai_risk_score: 10, missing_information: ['photo of damage'] };
} else if (has('burst pipe', 'geyser', 'water', 'leak')) {
  a = { claim_type: 'water_damage', severity: 'medium', ai_risk_score: 30, missing_information: ["plumber's report", 'photos of damage'] };
} else if (has('stolen', 'theft', 'hijack')) {
  a = { claim_type: 'theft', severity: 'high', ai_risk_score: 55, missing_information: ['police case number'] };
} else {
  a = { claim_type: 'other', severity: 'medium', ai_risk_score: 35, missing_information: ['photos of damage'] };
}

const fraud_indicators = [];
if (has('cash', 'urgent', 'asap', 'today')) {
  fraud_indicators.push('urgency_language', 'cash_payment_request');
  a.ai_risk_score += 25;
}
if (has('ignore previous', 'ignore all previous', 'system prompt', 'you are now', 'instructions')) {
  fraud_indicators.push('prompt_injection_attempt');
  a.ai_risk_score += 30;
}

return [{
  json: {
    injection_check,
    output: {
      ...a,
      ai_risk_score: Math.min(a.ai_risk_score, 100),
      fraud_indicators,
      summary: `Mock analysis: ${a.claim_type.replace('_', ' ')} claim, ${a.severity} severity.`,
    },
  },
}];

// ── Normalise AI result ──────────────────────────────────────────
// Receives ONE item from whichever branch ran: a success ({ output }) or an
// error-output item ({ error }). Never trusts the model: every field is
// checked against the schema. Anything wrong -> ai.status = 'failed', which
// Chunk D routes to manual review.
const ctx = $('Encrypt_PII_Func').first().json;   // claim (no PII) + policy context
const item = $input.first().json;

const mode = String($env.LLM_MODE || '').toLowerCase();
const model = { mock: 'mock', openai: $env.OPENAI_MODEL, anthropic: $env.ANTHROPIC_MODEL, ollama: $env.OLLAMA_MODEL }[mode] || `unknown mode "${mode}"`;

const CLAIM_TYPES = ['windscreen', 'collision', 'theft', 'water_damage', 'fire', 'storm', 'burglary',
  'accidental_damage', 'lost_baggage', 'medical', 'other'];
const SEVERITIES = ['low', 'medium', 'high', 'critical'];
const INDICATORS = ['new_policy_concern', 'vague_description', 'inconsistent_details', 'urgency_language',
  'cash_payment_request', 'amount_seems_inflated', 'third_party_pressure', 'prompt_injection_attempt', 'other'];

const problems = [];
const warnings = [];
const isStrArray = (v) => Array.isArray(v) && v.every((x) => typeof x === 'string');
const norm = (s) => String(s).trim().toLowerCase().replace(/[\s-]+/g, '_');

let ai = null;
if (item.error) {
  const msg = typeof item.error === 'string' ? item.error : (item.error.message || JSON.stringify(item.error));
  problems.push(`llm_error: ${msg.slice(0, 300)}`);
} else if (!['mock', 'openai', 'anthropic', 'ollama'].includes(mode)) {
  problems.push(`unknown LLM_MODE "${mode}"`);
} else if (!item.output || typeof item.output !== 'object') {
  problems.push('no structured output from model');
} else {
  const o = item.output;
  const claim_type = norm(o.claim_type ?? '');
  const severity = norm(o.severity ?? '');
  const score = Number(o.ai_risk_score);

  if (!CLAIM_TYPES.includes(claim_type)) problems.push(`invalid claim_type "${o.claim_type}"`);
  if (!SEVERITIES.includes(severity)) problems.push(`invalid severity "${o.severity}"`);
  if (typeof o.ai_risk_score !== 'number' && typeof o.ai_risk_score !== 'string') problems.push('ai_risk_score missing');
  else if (!Number.isFinite(score)) problems.push(`ai_risk_score not a number "${o.ai_risk_score}"`);
  if (typeof o.summary !== 'string' || !o.summary.trim()) problems.push('summary missing');
  if (!isStrArray(o.fraud_indicators ?? [])) problems.push('fraud_indicators must be a list of strings');
  if (!isStrArray(o.missing_information ?? [])) problems.push('missing_information must be a list of strings');

  if (problems.length === 0) {
    // Known vocabulary only; anything unexpected is kept as "other" and noted.
    const indicators = [...new Set((o.fraud_indicators ?? []).map((x) => {
      const n = norm(x);
      if (INDICATORS.includes(n)) return n;
      warnings.push(`unknown indicator "${x}" stored as other`);
      return 'other';
    }))];
    const clamped = Math.max(0, Math.min(100, Math.round(score)));
    if (clamped !== score) warnings.push(`ai_risk_score ${score} clamped to ${clamped}`);

    ai = {
      claim_type,
      severity,
      summary: o.summary.trim().slice(0, 500),
      fraud_indicators: indicators,
      ai_risk_score: clamped,
      missing_information: (o.missing_information ?? []).map((s) => s.trim()).filter(Boolean).slice(0, 10),
    };
  }
}

// ── Injection detector verdict (independent of the analysis above) ──
const DETECTOR_THRESHOLD = 0.7;
let injection_check = { flagged: false, confidence: null, failed: true };
if (mode === 'mock') {
  if (item.injection_check) injection_check = item.injection_check;
} else if (['openai', 'anthropic', 'ollama'].includes(mode)) {
  const det = { openai: 'OpenAI_Detector', anthropic: 'Anthropic_Detector', ollama: 'Ollama_Detector' }[mode];
  try {
    const okItems = $(det).all(0);
    const errItems = $(det).all(1);
    if (okItems.length) {
      const o = okItems[0].json.output || {};
      const conf = Number(o.confidence);
      const valid = typeof o.flagged === 'boolean' && Number.isFinite(conf);
      injection_check = valid
        ? { flagged: o.flagged && conf >= DETECTOR_THRESHOLD, confidence: conf, failed: false }
        : { flagged: false, confidence: null, failed: true, error: 'detector output did not match schema' };
    } else if (errItems.length) {
      injection_check = { flagged: false, confidence: null, failed: true, error: String(errItems[0].json.error || 'error').slice(0, 200) };
    }
  } catch (err) {
    injection_check.error = `detector ${det} did not run`;
  }
}

return [{
  json: {
    ...ctx,
    ai: {
      injection_check,
      status: ai ? 'ok' : 'failed',
      mode,
      model,
      problems,
      warnings,
      claim_type: ai?.claim_type ?? null,
      severity: ai?.severity ?? null,
      summary: ai?.summary ?? null,
      fraud_indicators: ai?.fraud_indicators ?? [],
      ai_risk_score: ai?.ai_risk_score ?? null,
      missing_information: ai?.missing_information ?? [],
    },
  },
}];

// ── ClaimFlow PII crypto ──────────────────────────────────────────
// Single source of truth for field-level encryption. Used by:
//   * the Encrypt_PII_Func Code node (this source is copied into the workflow)
//   * scripts/encrypt-seed-pii.js (require()d directly)
// Format: v1:<iv b64>:<auth tag b64>:<ciphertext b64>   (AES-256-GCM)
// The field name ("name" | "email" | "phone") is bound as associated data, so a
// ciphertext moved to a different column will not decrypt. See docs/security.md.
const crypto = require('crypto');

function piiKeys(env) {
  const key = Buffer.from(String(env.CLAIMFLOW_PII_KEY || ''), 'base64');
  const hmacKey = Buffer.from(String(env.CLAIMFLOW_PII_HMAC_KEY || ''), 'base64');
  if (key.length !== 32) throw new Error('CLAIMFLOW_PII_KEY must be 32 random bytes, base64-encoded');
  if (hmacKey.length !== 32) throw new Error('CLAIMFLOW_PII_HMAC_KEY must be 32 random bytes, base64-encoded');
  if (key.equals(hmacKey)) throw new Error('CLAIMFLOW_PII_KEY and CLAIMFLOW_PII_HMAC_KEY must differ');
  return { v1: key, hmacKey };
}

function encryptField(value, field, keys) {
  if (value === null || value === undefined || String(value).trim() === '') return null;
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', keys.v1, iv);
  cipher.setAAD(Buffer.from(field, 'utf8'));
  const ct = Buffer.concat([cipher.update(String(value), 'utf8'), cipher.final()]);
  return ['v1', iv.toString('base64'), cipher.getAuthTag().toString('base64'), ct.toString('base64')].join(':');
}

function decryptField(token, field, keys) {
  if (token === null || token === undefined) return null;
  const [version, iv, tag, ct] = String(token).split(':');
  const key = keys[version];
  if (!key || !iv || !tag || ct === undefined) throw new Error(`Unsupported or malformed ciphertext (${version})`);
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, Buffer.from(iv, 'base64'));
  decipher.setAAD(Buffer.from(field, 'utf8'));
  decipher.setAuthTag(Buffer.from(tag, 'base64'));
  return Buffer.concat([decipher.update(Buffer.from(ct, 'base64')), decipher.final()]).toString('utf8');
}

// Deterministic, non-reversible lookup key for exact-match email searches.
function blindIndex(email, keys) {
  return crypto.createHmac('sha256', keys.hmacKey).update(String(email).trim().toLowerCase(), 'utf8').digest('hex');
}

// ── Encrypt PII ───────────────────────────────────────────────────
// Everything after this node carries ciphertext only: name, email and phone are
// removed from the claim, and the raw payload's claimant block is redacted.
// Library above is copied verbatim from scripts/lib/pii-crypto.js (setup.sh uses the same file).
const keys = piiKeys($env);
const e = $input.first().json;
const { claimant_name, claimant_email, claimant_phone, ...claim } = e.claim;

const pii = {
  name_enc:   encryptField(claimant_name, 'name', keys),
  email_enc:  encryptField(claimant_email, 'email', keys),
  email_hmac: blindIndex(claimant_email, keys),
  phone_enc:  encryptField(claimant_phone, 'phone', keys),
};

const raw = { ...(e.raw_payload || {}) };
if (raw.claimant !== undefined) {
  raw.claimant = raw.claimant && typeof raw.claimant === 'object'
    ? Object.fromEntries(Object.keys(raw.claimant).map((k) => [k, '[encrypted]']))
    : '[encrypted]';
}

return [{ json: { ...e, claim, pii, raw_payload: raw } }];

// ── Apply rules, blend score, pick route ─────────────────────────
// Deterministic and explainable: every flag records why it fired, and the route
// records which condition decided it. The LLM never decides the route.
// All weights and thresholds live in CONFIG.
const CONFIG = {
  weights: { ai: 0.6, rules: 0.4 },
  rules: {
    new_policy:               { points: 25, days: 30 },
    late_reporting:           { points: 15, days: 30 },
    near_sum_insured:         { points: 20, ratio: 0.9 },
    frequent_claimant:        { points: 20, priorClaims: 2 },
    round_amount:             { points: 10, minAmount: 10000, multipleOf: 1000 },
    cash_or_urgency_language: { points: 15, pattern: /\b(cash|urgent(ly)?|asap|today|different account)\b/i },
    model_rule_disagreement:  { points: 15, aiAtMost: 20, rulesAtLeast: 40 },
  },
  injection: {
    // Tripwire only: cheap, high precision, easy to evade. See docs (layered defence).
    pattern: new RegExp([
      String.raw`\b(ignore|disregard|forget|override)\b.{0,40}\b(previous|prior|above|all|earlier|these|your)\b.{0,25}\b(instructions?|rules|prompts?|guidelines)\b`,
      String.raw`\bignoreer\b.{0,40}\binstruksies\b`,
      String.raw`(^|[\s.])(system|assistant)\s*(prompt|message)?\s*:`,
      String.raw`\byou are now\b`,
      String.raw`\b(set|make|give|record|keep)\b.{0,40}\b(risk|score|risk score)\b.{0,25}\b(0|zero|low)\b`,
      String.raw`\[tag removed\]|<\s*\/?\s*claim_description\s*>`,
      String.raw`\b(ai_risk_score|fraud_indicators|claim_description)\b`,
    ].join('|'), 'i'),
    detectorIsHard: true,
  },
  // Hard flags = the two layers that measured reliably. The analysis model's self-report is
  // only scored: on llama3.2:3b it caught 0/5 attacks and raised 1/4 false alarms.
  hardFlags: ['prompt_injection_pattern', 'injection_detector'],
  aiReportedInjectionPoints: 15,
  noFastTrackFlags: ['injection_check_unavailable'],
  routing: { fraudScore: 60, fraudFlagCount: 3, fastTrackMaxScore: 25, fastTrackMaxAmount: 20000 },
  statusByRoute: {
    fast_track: 'approved_for_assessment', standard: 'in_standard_queue',
    fraud_review: 'pending_fraud_review', manual_review: 'pending_manual_review',
  },
};

const e = $input.first().json;            // from Normalise_AI_Func: claim, policy, pii, ai, ...
const c = e.claim;
const p = e.policy;
const ai = e.ai;
const today = $now.setZone('Africa/Johannesburg').startOf('day');
const days = (from, to) => Math.round(DateTime.fromISO(to).diff(DateTime.fromISO(from), 'days').days);
const flags = [];
const add = (code, points, detail) => flags.push({ code, points, detail });
const R = CONFIG.rules;

// ── Scored rules ──
const sincePolicyStart = days(p.start_date, c.incident_date);
if (sincePolicyStart >= 0 && sincePolicyStart <= R.new_policy.days)
  add('new_policy', R.new_policy.points, `incident ${sincePolicyStart} days after policy start`);

const reportedAfter = Math.round(today.diff(DateTime.fromISO(c.incident_date), 'days').days);
if (reportedAfter > R.late_reporting.days)
  add('late_reporting', R.late_reporting.points, `reported ${reportedAfter} days after the incident`);

const ratio = c.claimed_amount / p.sum_insured;
if (ratio >= R.near_sum_insured.ratio)
  add('near_sum_insured', R.near_sum_insured.points, `claim is ${Math.round(ratio * 100)}% of the sum insured`);

if ((e.prior_claims_12m ?? 0) >= R.frequent_claimant.priorClaims)
  add('frequent_claimant', R.frequent_claimant.points, `${e.prior_claims_12m} prior claims in the last 12 months`);

if (c.claimed_amount >= R.round_amount.minAmount && c.claimed_amount % R.round_amount.multipleOf === 0)
  add('round_amount', R.round_amount.points, `round amount R${c.claimed_amount}`);

const urgency = c.description.match(R.cash_or_urgency_language.pattern);
if (urgency) add('cash_or_urgency_language', R.cash_or_urgency_language.points, `contains "${urgency[0]}"`);

// ── Injection layers (hard flags carry 0 points: they route, they don't distort the score) ──
const injection = c.description.match(CONFIG.injection.pattern);
if (injection) add('prompt_injection_pattern', 0, `tripwire matched "${injection[0].slice(0, 60)}"`);

const check = ai.injection_check || { flagged: false, failed: true, confidence: null };
if (check.failed) add('injection_check_unavailable', 0, 'injection detector did not return a verdict');
else if (check.flagged) {
  if (CONFIG.injection.detectorIsHard) add('injection_detector', 0, `detector confidence ${check.confidence}`);
  else add('injection_detector', 25, `detector confidence ${check.confidence} (scored, not hard)`);
}

if ((ai.fraud_indicators || []).includes('prompt_injection_attempt'))
  add('ai_reported_injection', CONFIG.aiReportedInjectionPoints, 'analysis model reported prompt_injection_attempt');

// ── Scores ──
const scoredBeforeConsistency = Math.min(100, flags.reduce((s, f) => s + f.points, 0));
const aiOk = ai.status === 'ok' && Number.isFinite(ai.ai_risk_score);
if (aiOk && ai.ai_risk_score <= R.model_rule_disagreement.aiAtMost && scoredBeforeConsistency >= R.model_rule_disagreement.rulesAtLeast)
  add('model_rule_disagreement', R.model_rule_disagreement.points,
    `AI score ${ai.ai_risk_score} vs rule score ${scoredBeforeConsistency}`);

const rule_score = Math.min(100, flags.reduce((s, f) => s + f.points, 0));
const final_risk_score = aiOk
  ? Math.round(CONFIG.weights.ai * ai.ai_risk_score + CONFIG.weights.rules * rule_score)
  : rule_score;

// ── Route (first match wins) ──
const hard = flags.filter((f) => CONFIG.hardFlags.includes(f.code)).map((f) => f.code);
const scoredFlags = flags.filter((f) => f.points > 0);
const R2 = CONFIG.routing;
const reasons = [];
let route;
if (hard.length) {
  route = 'fraud_review'; reasons.push(`hard flag: ${hard.join(', ')}`);
} else if (!aiOk) {
  route = 'manual_review'; reasons.push(`AI analysis failed: ${(ai.problems || []).join('; ').slice(0, 200)}`);
} else if (final_risk_score >= R2.fraudScore || scoredFlags.length >= R2.fraudFlagCount) {
  route = 'fraud_review';
  if (final_risk_score >= R2.fraudScore) reasons.push(`final score ${final_risk_score} >= ${R2.fraudScore}`);
  if (scoredFlags.length >= R2.fraudFlagCount) reasons.push(`${scoredFlags.length} scored rule flags`);
} else if (final_risk_score < R2.fastTrackMaxScore && c.claimed_amount <= R2.fastTrackMaxAmount && flags.length === 0) {
  route = 'fast_track';
  reasons.push(`final score ${final_risk_score} < ${R2.fastTrackMaxScore}, amount R${c.claimed_amount} <= R${R2.fastTrackMaxAmount}, no flags`);
} else {
  route = 'standard';
  if (final_risk_score >= R2.fastTrackMaxScore) reasons.push(`final score ${final_risk_score} too high for fast track`);
  if (c.claimed_amount > R2.fastTrackMaxAmount) reasons.push(`amount R${c.claimed_amount} above fast-track limit`);
  if (flags.length) reasons.push(`has flags: ${flags.map((f) => f.code).join(', ')}`);
}

return [{
  json: {
    ...e,
    decision: {
      rule_flags: flags,
      rule_score,
      final_risk_score,
      route,
      route_reasons: reasons,
      status: CONFIG.statusByRoute[route],
    },
  },
}];

// ── ClaimFlow signed status links ─────────────────────────────────
// Claim references are sequential, so the Status API needs proof the caller was given the
// link: t = first 32 hex chars of HMAC-SHA256(CLAIMFLOW_STATUS_LINK_KEY, claim_ref).
// Copied into the Code nodes that build or check links (same pattern as pii-crypto.js).
const linkCrypto = require('crypto');

function statusToken(claimRef, env) {
  const key = Buffer.from(String(env.CLAIMFLOW_STATUS_LINK_KEY || ''), 'base64');
  if (key.length < 32) throw new Error('CLAIMFLOW_STATUS_LINK_KEY must be at least 32 random bytes, base64-encoded');
  return linkCrypto.createHmac('sha256', key).update(`status:${claimRef}`, 'utf8').digest('hex').slice(0, 32);
}

function statusUrl(claimRef, env) {
  return `${env.WEBHOOK_URL}webhook/claims/status?ref=${encodeURIComponent(claimRef)}&t=${statusToken(claimRef, env)}`;
}

// Constant-time comparison so response timing doesn't reveal how much of a token matched.
function statusTokenValid(claimRef, token, env) {
  const expected = Buffer.from(statusToken(claimRef, env), 'utf8');
  const given = Buffer.from(String(token || ''), 'utf8');
  return given.length === expected.length && linkCrypto.timingSafeEqual(given, expected);
}

// ── Add the signed status link ───────────────────────────────────
const it = $input.first().json;
const ref = it.claim_ref || it.existing_claim_ref;
return [{ json: { ...it, status_url: ref ? statusUrl(ref, $env) : null } }];

